<script>
(function(){var type=document.getElementById('locationType'),parent=document.getElementById('locationParent');function update(){var t=type.value;Array.from(parent.options).forEach(function(o){if(!o.value)return;var allowed={city:['country'],district:['city'],neighborhood:['district']}[t]||[];o.hidden=allowed.indexOf(o.dataset.type)<0});parent.value='0';parent.disabled=t==='country';if(t==='country'){parent.value='0'}else if(parent.options.length>1){var first=Array.from(parent.options).find(function(o){return o.value&& !o.hidden});if(first)parent.value=first.value}}type.addEventListener('change',update);update()})();
</script></body></html>